    public List<CarePlan> testGetAll() throws Throwable {
    LOGGER.info( "CarePlanTest:testGetAll() - Retrieving Collection of CarePlans:" );

    StringBuilder msg = new StringBuilder( "-- Failed to get all CarePlan : " );
    List<CarePlan> collection  = null;

    try {
        // call the static get method on the CarePlanService
        collection = service.getAllCarePlan();

        if ( collection == null || collection.size() == 0 ) {
            LOGGER.warning( unexpectedErrorMsg );
            LOGGER.warning( "-- " + msg.toString() + " Empty collection returned."  );
        }
        else {
            // Now print out the values
            CarePlan currEntity  = null;
            Iterator<CarePlan> iter = collection.iterator();

            while( iter.hasNext() ) {
                // Retrieve the entity
                currEntity = iter.next();

                assertNotNull( currEntity,"-- null value object in Collection." );
                assertNotNull( currEntity.getCarePlanId(), "-- value object in Collection has a null primary key" );

                LOGGER.info( " - " + currEntity.toString() );
            }
        }
    }
    catch ( Throwable e ){
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() );

        throw e;
    }

    return( collection );
}

